# -*- coding: utf-8 -*-
"""
Direct tests for the seven modules in helpdesk/templatetags/.

Each filter is exercised three ways: the normal case, the empty/None case, and
the case the filter was actually written to handle. Where the filter is meant to
be reached from a template, it is also rendered through the template engine, so
the registration name and the escaping behaviour are pinned too, not just the
Python function.
"""

import datetime

from django.contrib.auth.models import AnonymousUser
from django.template import Context, Template
from django.test import TestCase
from django.urls import NoReverseMatch, reverse
from django.utils.safestring import SafeString

from helpdesk import settings as helpdesk_settings
from helpdesk.models import Queue, SavedSearch, Ticket
from helpdesk.templatetags.helpdesk_staff import helpdesk_staff
from helpdesk.templatetags.helpdesk_util import datetime_string_format, get
from helpdesk.templatetags.in_list import in_list
from helpdesk.templatetags.load_helpdesk_settings import load_helpdesk_settings
from helpdesk.templatetags.saved_queries import saved_queries
from helpdesk.templatetags.ticket_to_link import num_to_link
from helpdesk.templatetags.user_admin_url import user_admin_url
from helpdesk.tests.helpers import get_staff_user, get_user


def render(template_string, **context):
    return Template(template_string).render(Context(context))


class IsHelpdeskStaffFilterTests(TestCase):
    """helpdesk_staff.py - {{ user|is_helpdesk_staff }}"""

    def test_staff_user_is_helpdesk_staff(self):
        self.assertTrue(helpdesk_staff(get_staff_user()))

    def test_authenticated_non_staff_user_is_not_helpdesk_staff(self):
        self.assertFalse(helpdesk_staff(get_user(username="plain.user")))

    def test_inactive_staff_user_is_not_helpdesk_staff(self):
        user = get_staff_user()
        user.is_active = False
        user.save()
        self.assertFalse(helpdesk_staff(user))

    def test_anonymous_user_is_not_helpdesk_staff(self):
        self.assertFalse(helpdesk_staff(AnonymousUser()))

    def test_none_is_swallowed_and_returns_falsy(self):
        """The filter catches its own exceptions so a template never 500s on a
        missing user variable; the implicit None it returns must stay falsy."""
        self.assertFalse(helpdesk_staff(None))

    def test_registered_under_is_helpdesk_staff_in_templates(self):
        out = render(
            "{% load helpdesk_staff %}{% if user|is_helpdesk_staff %}yes{% else %}no{% endif %}",
            user=get_staff_user(),
        )
        self.assertEqual(out, "yes")


class InListFilterTests(TestCase):
    """in_list.py - {% if x|in_list:ys %}"""

    def test_value_present_in_list(self):
        self.assertTrue(in_list("pizza", ["pizza", "pie"]))

    def test_value_absent_from_list(self):
        self.assertFalse(in_list("sprouts", ["pizza", "pie"]))

    def test_empty_list_never_contains_anything(self):
        self.assertFalse(in_list("pizza", []))

    def test_none_container_is_treated_as_empty(self):
        """The `or []` guard is the whole point of the filter: an unset context
        variable arrives as None and must not raise."""
        self.assertFalse(in_list("pizza", None))

    def test_membership_of_any_container_type(self):
        self.assertTrue(in_list("zz", "buzzer"))
        self.assertTrue(in_list(2, (1, 2, 3)))
        self.assertTrue(in_list("k", {"k": 1}))

    def test_registered_in_templates(self):
        out = render(
            "{% load in_list %}{% if food|in_list:best %}fav{% else %}meh{% endif %}",
            food="pizza",
            best=["pizza"],
        )
        self.assertEqual(out, "fav")


class LoadHelpdeskSettingsFilterTests(TestCase):
    """load_helpdesk_settings.py - {{ request|load_helpdesk_settings }}"""

    def test_returns_the_helpdesk_settings_module(self):
        self.assertIs(load_helpdesk_settings(None), helpdesk_settings)

    def test_does_not_depend_on_the_request_argument(self):
        """The argument is only there to make it usable as a filter on request."""
        self.assertIs(load_helpdesk_settings(object()), helpdesk_settings)

    def test_exposes_a_known_setting(self):
        self.assertEqual(
            load_helpdesk_settings(None).HELPDESK_KB_ENABLED,
            helpdesk_settings.HELPDESK_KB_ENABLED,
        )

    def test_absent_setting_renders_empty_rather_than_raising(self):
        """Templates read settings off the returned module by name. A name that
        does not exist must render as the empty string, not blow up the page."""
        out = render(
            "{% load load_helpdesk_settings %}"
            "[{{ request|load_helpdesk_settings.HELPDESK_NO_SUCH_SETTING }}]",
            request=None,
        )
        self.assertEqual(out, "[]")

    def test_reads_a_real_setting_through_a_template(self):
        out = render(
            "{% load load_helpdesk_settings %}"
            "{% with s=request|load_helpdesk_settings %}{{ s.HELPDESK_KB_ENABLED }}{% endwith %}",
            request=None,
        )
        self.assertEqual(out, str(helpdesk_settings.HELPDESK_KB_ENABLED))


class SavedQueriesFilterTests(TestCase):
    """saved_queries.py - {{ user|saved_queries }}"""

    def setUp(self):
        self.user = get_user(username="query.owner")
        self.other = get_user(username="query.stranger")
        self.mine = SavedSearch.objects.create(
            user=self.user, title="Mine", shared=False, query="{}"
        )
        self.theirs = SavedSearch.objects.create(
            user=self.other, title="Theirs", shared=False, query="{}"
        )
        self.shared = SavedSearch.objects.create(
            user=self.other, title="Shared", shared=True, query="{}"
        )

    def test_returns_own_and_shared_queries_but_not_other_peoples_private_ones(self):
        self.assertCountEqual(
            list(saved_queries(self.user)), [self.mine, self.shared]
        )

    def test_anonymous_user_sees_only_shared_queries(self):
        self.assertCountEqual(list(saved_queries(AnonymousUser())), [self.shared])

    def test_returns_empty_queryset_when_nothing_is_saved(self):
        SavedSearch.objects.all().delete()
        self.assertEqual(list(saved_queries(self.user)), [])

    def test_returns_empty_string_when_the_user_is_unusable(self):
        """The filter swallows its own errors so a broken context variable
        degrades to an empty loop instead of a 500."""
        self.assertEqual(saved_queries(None), "")

    def test_registered_in_templates(self):
        out = render(
            "{% load saved_queries %}{% for q in user|saved_queries %}{{ q.title }},{% endfor %}",
            user=self.user,
        )
        self.assertCountEqual(out.rstrip(",").split(","), ["Mine", "Shared"])


class TicketToLinkFilterTests(TestCase):
    """ticket_to_link.py - {{ comment|num_to_link }}"""

    def setUp(self):
        self.queue = Queue.objects.create(title="Link Q", slug="link-q")
        self.ticket = Ticket.objects.create(
            title="Linked ticket", queue=self.queue, status=Ticket.OPEN_STATUS
        )

    def expected_link(self, ticket):
        return (
            "<a href='%s' class='ticket_link_status ticket_link_status_%s'>#%s</a>"
            % (
                reverse("helpdesk:view", args=[ticket.id]),
                ticket.get_status_display(),
                ticket.id,
            )
        )

    def test_expands_a_reference_to_an_existing_ticket(self):
        out = num_to_link("see #%s now" % self.ticket.id)
        self.assertEqual(out, "see %s now" % self.expected_link(self.ticket))

    def test_status_class_follows_the_ticket_status(self):
        self.ticket.status = Ticket.CLOSED_STATUS
        self.ticket.save()
        self.assertIn(
            "ticket_link_status_%s" % self.ticket.get_status_display(),
            num_to_link("#%s" % self.ticket.id),
        )

    def test_empty_string_is_returned_unchanged_and_unwrapped(self):
        self.assertEqual(num_to_link(""), "")

    def test_missing_ticket_is_left_as_plain_text(self):
        """A #number with no ticket behind it must not become a dead link."""
        missing = self.ticket.id + 5000
        self.assertFalse(Ticket.objects.filter(id=missing).exists())
        self.assertEqual(num_to_link("see #%s" % missing), "see #%s" % missing)

    def test_text_without_any_reference_is_unchanged(self):
        self.assertEqual(num_to_link("no ticket here"), "no ticket here")

    def test_html_entities_are_not_mistaken_for_references(self):
        """The `[^&]` guard exists so that an escaped entity such as &#39; is
        not read as a reference to ticket 39."""
        text = "it&#%s; is quoted" % self.ticket.id
        self.assertEqual(num_to_link(text), text)

    def test_expands_every_reference_in_the_text(self):
        second = Ticket.objects.create(
            title="Second", queue=self.queue, status=Ticket.OPEN_STATUS
        )
        out = num_to_link("#%s and #%s" % (self.ticket.id, second.id))
        self.assertIn(self.expected_link(self.ticket), out)
