    def test_result_is_marked_safe_so_the_anchor_survives_rendering(self):
        out = num_to_link("#%s" % self.ticket.id)
        self.assertIsInstance(out, SafeString)
        self.assertEqual(
            render("{% load ticket_to_link %}{{ text|num_to_link }}",
                   text="#%s" % self.ticket.id),
            self.expected_link(self.ticket),
        )


