Two things are worth testing here. The `list_display` entries that are methods
rather than model fields have to return what the column header claims, and
`QueueAdmin.delete_queryset` has to keep going through `Queue.delete()` - a
plain `queryset.delete()` would bypass it and leave the queue's auto-created
Permission behind.

Every changelist is also rendered through the real admin site, which is what
runs Django's admin system checks against these ModelAdmin declarations.
"""

import datetime

from django.contrib import admin as django_admin
from django.contrib.auth.models import Permission
from django.core.management import call_command
from django.test import TestCase
from django.urls import reverse

from helpdesk import settings as helpdesk_settings
from helpdesk.admin import (
    ChecklistAdmin,
    CustomFieldAdmin,
    EmailTemplateAdmin,
    FollowUpAdmin,
    IgnoreEmailAdmin,
    QueueAdmin,
    TicketAdmin,
)
from helpdesk.models import (
    Checklist,
    CustomField,
    EmailTemplate,
    FollowUp,
    IgnoreEmail,
    Queue,
    Ticket,
)
from helpdesk.tests.helpers import get_user


def make_queue(**kwargs):
    kwargs.setdefault("title", "Admin Q")
    kwargs.setdefault("slug", "admin-q")
    return Queue.objects.create(**kwargs)


def make_ticket(queue=None, **kwargs):
    kwargs.setdefault("title", "Admin ticket")
    kwargs.setdefault("status", Ticket.OPEN_STATUS)
    return Ticket.objects.create(queue=queue or make_queue(), **kwargs)


class AdminSystemChecksTests(TestCase):
    """The declarations themselves - fields, inlines, autocomplete targets."""

    def test_admin_checks_pass(self):
        """`check` fails loudly on any admin.E*** error, which is where a
        ModelAdmin option removed or tightened by a Django release shows up."""
        call_command("check", "helpdesk")

    def test_every_helpdesk_model_admin_is_registered(self):
        registered = {model._meta.label for model in django_admin.site._registry}
        for model in (Queue, Ticket, FollowUp, CustomField, EmailTemplate,
                      IgnoreEmail, Checklist):
            self.assertIn(model._meta.label, registered)


class QueueAdminTests(TestCase):
    def setUp(self):
        self.admin = QueueAdmin(Queue, django_admin.site)

    def test_time_spent_shows_spent_over_dedicated_when_both_are_set(self):
        queue = make_queue(dedicated_time=datetime.timedelta(hours=5))
        ticket = make_ticket(queue=queue)
        FollowUp.objects.create(
            ticket=ticket,
            title="work",
            date=ticket.created,
            time_spent=datetime.timedelta(hours=2),
        )
        self.assertEqual(
            self.admin.time_spent(queue),
            "{} / {}".format(datetime.timedelta(hours=2), datetime.timedelta(hours=5)),
        )

    def test_time_spent_shows_the_bare_total_when_no_time_is_dedicated(self):
        queue = make_queue()
        ticket = make_ticket(queue=queue)
        FollowUp.objects.create(
            ticket=ticket,
            title="work",
            date=ticket.created,
            time_spent=datetime.timedelta(hours=3),
        )
        self.assertEqual(self.admin.time_spent(queue), datetime.timedelta(hours=3))

    def test_time_spent_is_a_dash_when_nothing_has_been_spent(self):
        self.assertEqual(self.admin.time_spent(make_queue()), "-")

    def test_delete_queryset_deletes_every_queue(self):
        make_queue(title="One", slug="one")
        make_queue(title="Two", slug="two")
        self.admin.delete_queryset(None, Queue.objects.all())
        self.assertEqual(Queue.objects.count(), 0)

    def test_delete_queryset_also_removes_the_per_queue_permission(self):
        """This is why the hook is overridden at all: `queryset.delete()` runs
        a bulk SQL delete and never calls `Queue.delete()`, so the Permission
        created alongside the queue would be orphaned."""
        helpdesk_settings.HELPDESK_ENABLE_PER_QUEUE_STAFF_PERMISSION = True
        try:
            queue = make_queue(title="Perm Q", slug="perm-q")
            codename = queue.permission_name[9:]
            self.assertTrue(Permission.objects.filter(codename=codename).exists())

            self.admin.delete_queryset(None, Queue.objects.filter(pk=queue.pk))

            self.assertFalse(Queue.objects.filter(pk=queue.pk).exists())
            self.assertFalse(Permission.objects.filter(codename=codename).exists())
        finally:
            helpdesk_settings.HELPDESK_ENABLE_PER_QUEUE_STAFF_PERMISSION = False

    def test_delete_queryset_on_an_empty_queryset_is_a_no_op(self):
        make_queue()
        self.admin.delete_queryset(None, Queue.objects.none())
        self.assertEqual(Queue.objects.count(), 1)

    def test_slug_is_prepopulated_from_the_title(self):
        self.assertEqual(self.admin.prepopulated_fields, {"slug": ("title",)})


