    def setUp(self):
        self.user = get_user(
            username="admin.super", is_staff=True, is_superuser=True
        )
        self.client.force_login(self.user)

    def changelist(self, model):
        return reverse(
            "admin:%s_%s_changelist" % (model._meta.app_label, model._meta.model_name)
        )

    def test_queue_changelist_renders_the_time_spent_column(self):
        make_queue()
        response = self.client.get(self.changelist(Queue))
        self.assertEqual(response.status_code, 200)
        self.assertContains(response, "Time spent")

    def test_ticket_changelist_renders_the_masked_submitter_email(self):
        make_ticket(submitter_email="submitter@example.com")
        response = self.client.get(self.changelist(Ticket))
        self.assertEqual(response.status_code, 200)
        self.assertContains(response, "su*******@e*********m")
        self.assertNotContains(response, "submitter@example.com")

    def test_followup_changelist_renders(self):
        ticket = make_ticket()
        FollowUp.objects.create(ticket=ticket, title="note", date=ticket.created)
        response = self.client.get(self.changelist(FollowUp))
        self.assertEqual(response.status_code, 200)
        self.assertContains(response, ticket.ticket_for_url)

    def test_every_registered_helpdesk_changelist_renders_when_empty(self):
        for model in django_admin.site._registry:
            if model._meta.app_label != "helpdesk":
                continue
            with self.subTest(model=model._meta.label):
                response = self.client.get(self.changelist(model))
                self.assertEqual(response.status_code, 200)

    def test_admin_delete_action_removes_the_queue_and_its_permission(self):
        helpdesk_settings.HELPDESK_ENABLE_PER_QUEUE_STAFF_PERMISSION = True
        try:
            queue = make_queue(title="Action Q", slug="action-q")
            codename = queue.permission_name[9:]
            response = self.client.post(
                self.changelist(Queue),
                {
                    "action": "delete_selected",
                    "_selected_action": [str(queue.pk)],
                    "post": "yes",
                },
                follow=True,
            )
            self.assertEqual(response.status_code, 200)
            self.assertFalse(Queue.objects.filter(pk=queue.pk).exists())
            self.assertFalse(Permission.objects.filter(codename=codename).exists())
        finally:
            helpdesk_settings.HELPDESK_ENABLE_PER_QUEUE_STAFF_PERMISSION = False


